ALTER TABLE public.profiles ADD COLUMN account_type text NOT NULL DEFAULT 'individual' CHECK(account_type IN('individual','company')),ADD COLUMN national_id_verified_at timestamptz;
CREATE TABLE public.companies(user_id uuid PRIMARY KEY,name text NOT NULL,commercial_number text NOT NULL,commercial_path text NOT NULL,tax_number text NOT NULL,tax_path text NOT NULL,representative_name text NOT NULL,representative_national_id text NOT NULL,representative_phone text NOT NULL,representative_role text NOT NULL);
GRANT SELECT,INSERT,UPDATE ON public.companies TO authenticated;GRANT ALL ON public.companies TO service_role;ALTER TABLE public.companies ENABLE ROW LEVEL SECURITY;CREATE POLICY company_owner ON public.companies FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());CREATE POLICY company_admin_read ON public.companies FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.lock_verified_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.national_id_verified_at IS NOT NULL AND (NEW.national_id IS DISTINCT FROM OLD.national_id OR NEW.full_name IS DISTINCT FROM OLD.full_name OR NEW.account_type IS DISTINCT FROM OLD.account_type OR NEW.requested_account_type IS DISTINCT FROM OLD.requested_account_type) THEN RAISE EXCEPTION 'Approved identity fields are read-only';END IF;IF NEW.national_id_verified_at IS DISTINCT FROM OLD.national_id_verified_at AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Verification requires administrator';END IF;RETURN NEW;END $$;CREATE TRIGGER lock_verified_identity BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.lock_verified_identity();
CREATE FUNCTION public.validate_company_documents() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM public.profiles WHERE id=OLD.user_id AND national_id_verified_at IS NOT NULL) AND (NEW.name IS DISTINCT FROM OLD.name OR NEW.commercial_number IS DISTINCT FROM OLD.commercial_number OR NEW.commercial_path IS DISTINCT FROM OLD.commercial_path OR NEW.tax_number IS DISTINCT FROM OLD.tax_number OR NEW.tax_path IS DISTINCT FROM OLD.tax_path OR NEW.representative_name IS DISTINCT FROM OLD.representative_name OR NEW.representative_national_id IS DISTINCT FROM OLD.representative_national_id OR NEW.representative_role IS DISTINCT FROM OLD.representative_role) THEN RAISE EXCEPTION 'Approved company identity is read-only';END IF;IF length(trim(NEW.name))=0 OR length(trim(NEW.commercial_number))=0 OR length(trim(NEW.tax_number))=0 OR length(trim(NEW.representative_name))=0 OR NEW.representative_national_id !~ '^[0-9]{14}$' OR length(trim(NEW.representative_phone))<7 OR length(trim(NEW.representative_role))=0 THEN RAISE EXCEPTION 'Company details required';END IF;IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='company-documents' AND name=NEW.commercial_path AND name LIKE NEW.user_id::text||'/%' AND metadata->>'mimetype'='application/pdf') OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='company-documents' AND name=NEW.tax_path AND name LIKE NEW.user_id::text||'/%' AND metadata->>'mimetype'='application/pdf') THEN RAISE EXCEPTION 'Stored company PDFs required';END IF;RETURN NEW;END $$;CREATE TRIGGER validate_company_documents BEFORE INSERT OR UPDATE ON public.companies FOR EACH ROW EXECUTE FUNCTION public.validate_company_documents();
CREATE POLICY company_file_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='company-documents' AND (storage.foldername(name))[1]=auth.uid()::text);CREATE POLICY company_file_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='company-documents' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin')));
CREATE TABLE public.documents(id integer PRIMARY KEY,name text NOT NULL);GRANT SELECT ON public.documents TO authenticated;GRANT ALL ON public.documents TO service_role;ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY;CREATE POLICY document_read ON public.documents FOR SELECT TO authenticated USING(true);
CREATE TABLE public.requirement_profiles(id text PRIMARY KEY,name text NOT NULL);GRANT SELECT ON public.requirement_profiles TO authenticated;GRANT ALL ON public.requirement_profiles TO service_role;ALTER TABLE public.requirement_profiles ENABLE ROW LEVEL SECURITY;CREATE POLICY requirement_read ON public.requirement_profiles FOR SELECT TO authenticated USING(true);
CREATE TABLE public.profile_documents(profile_id text REFERENCES public.requirement_profiles(id),document_id integer REFERENCES public.documents(id),is_required boolean NOT NULL DEFAULT true,condition text NOT NULL DEFAULT 'always' CHECK(condition IN('always','food_beverage')),PRIMARY KEY(profile_id,document_id));GRANT SELECT,INSERT,UPDATE,DELETE ON public.profile_documents TO authenticated;GRANT ALL ON public.profile_documents TO service_role;ALTER TABLE public.profile_documents ENABLE ROW LEVEL SECURITY;CREATE POLICY requirements_read ON public.profile_documents FOR SELECT TO authenticated USING(true);CREATE POLICY requirements_admin ON public.profile_documents FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
INSERT INTO public.documents VALUES(1,'تحقيق الشخصية (أفراد) أو الشكل القانوني (للشركات) أو توكيل رسمي بالإدارة في حالة التقديم بالمركز التكنولوجي'),(2,'مستخرج رسمي من السجل التجاري'),(3,'صورة من عقد الملكية / عقد الإيجار موثق بالشهر العقاري ومعتمد من شركة العاصمة الإدارية في التعامل واستخراج التراخيص، ويشار إليه في الخطاب'),(4,'صورة من رخصة البناء معتمدة بصورة طبق الأصل بخاتم الشركة'),(5,'إفادة من إدارة التراخيص بموقف المحل العام في حالة وجود رخصة بناء أو تقنين وضع العقار'),(6,'تقرير هندسي معتمد يثبت السلامة الإنشائية للعقار في حالة عدم وجود رخصة بناء أو تقنين وضع العقار أو مخالف لشروط الترخيص'),(7,'رسم توضيحي (كروكي) واضح به موقع المحل واسم الجهاز أو المنطقة واسم الشارع ورقم العقار (إن وجد)'),(8,'صورة من البطاقة الضريبية بعد الاطلاع على الأصل'),(9,'شهادات صحية للعاملين بالمحلات المتخصصة بتقديم وتحضير وتداول الأغذية والمشروبات'),(10,'صورة طبق الأصل من محضر الاستلام للمولات'),(11,'في حالة الإيجار من شركة العاصمة: صورة طبق الأصل من عقد الإيجار ومحضر الاستلام'),(12,'صورة من محضر الحماية المدنية للمبنى أو المحل المراد ترخيصه');
INSERT INTO public.requirement_profiles VALUES('standard','المتطلبات القياسية');INSERT INTO public.profile_documents(profile_id,document_id) SELECT 'standard',id FROM public.documents;
ALTER TABLE public.licensing_plots ADD COLUMN profile_id text NOT NULL DEFAULT 'standard' REFERENCES public.requirement_profiles(id);GRANT UPDATE ON public.licensing_plots TO authenticated;CREATE POLICY plot_admin_update ON public.licensing_plots FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
ALTER TABLE public.license_requests ADD COLUMN activity_category text NOT NULL DEFAULT 'other',ADD COLUMN required_document_snapshot jsonb NOT NULL DEFAULT '[]';ALTER TABLE public.license_requests DROP CONSTRAINT license_requests_status_check;ALTER TABLE public.license_requests ADD CONSTRAINT license_requests_status_check CHECK(status IN('awaiting_document_review','awaiting_payment','awaiting_payment_review','under_review','issued','rejected','needs_info'));
CREATE TABLE public.application_documents(request_id uuid REFERENCES public.license_requests(id),document_id integer REFERENCES public.documents(id),document_name text NOT NULL,path text NOT NULL,bucket text NOT NULL DEFAULT 'license-documents',PRIMARY KEY(request_id,document_id));GRANT SELECT ON public.application_documents TO authenticated;GRANT ALL ON public.application_documents TO service_role;ALTER TABLE public.application_documents ENABLE ROW LEVEL SECURITY;CREATE POLICY application_doc_read ON public.application_documents FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.license_requests r WHERE r.id=request_id AND(r.user_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE POLICY owner_request_events ON public.admin_request_events FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.license_requests r WHERE r.id=request_id AND r.user_id=auth.uid() AND r.deleted_at IS NULL));
CREATE FUNCTION public.required_plot_documents(p_property uuid,p_category text) RETURNS TABLE(id integer,name text) LANGUAGE sql STABLE SET search_path=public AS $$ SELECT d.id,d.name FROM public.licensing_plots p JOIN public.profile_documents pd ON pd.profile_id=p.profile_id JOIN public.documents d ON d.id=pd.document_id WHERE p.id=p_property AND pd.is_required ORDER BY d.id $$;REVOKE ALL ON FUNCTION public.required_plot_documents(uuid,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.required_plot_documents(uuid,text) TO authenticated;
ALTER FUNCTION public.validate_license_request() SECURITY DEFINER;
CREATE FUNCTION public.save_portal_account(p_data jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c jsonb;uid uuid:=auth.uid();BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Unauthorized';END IF;IF length(trim(p_data->>'full_name'))<2 OR p_data->>'national_id' !~ '^[0-9]{14}$' OR length(trim(p_data->>'phone'))<7 OR p_data->>'account_type' NOT IN('individual','company') THEN RAISE EXCEPTION 'Invalid profile';END IF;IF p_data->>'account_type'='company' THEN c:=p_data->'company';IF c IS NULL THEN RAISE EXCEPTION 'Company required';END IF;INSERT INTO public.companies(user_id,name,commercial_number,commercial_path,tax_number,tax_path,representative_name,representative_national_id,representative_phone,representative_role) VALUES(uid,c->>'name',c->>'commercial_number',c->>'commercial_path',c->>'tax_number',c->>'tax_path',c->>'representative_name',c->>'representative_national_id',c->>'representative_phone',c->>'representative_role') ON CONFLICT(user_id) DO UPDATE SET name=excluded.name,commercial_number=excluded.commercial_number,commercial_path=excluded.commercial_path,tax_number=excluded.tax_number,tax_path=excluded.tax_path,representative_name=excluded.representative_name,representative_national_id=excluded.representative_national_id,representative_phone=excluded.representative_phone,representative_role=excluded.representative_role;END IF;UPDATE public.profiles SET full_name=p_data->>'full_name',national_id=p_data->>'national_id',phone=p_data->>'phone',account_type=p_data->>'account_type' WHERE id=uid;IF NOT FOUND THEN RAISE EXCEPTION 'Profile unavailable';END IF;END $$;
CREATE FUNCTION public.save_contact_details(p_phone text,p_representative_phone text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR length(trim(p_phone)) NOT BETWEEN 7 AND 30 THEN RAISE EXCEPTION 'Valid contact phone required';END IF;UPDATE public.profiles SET phone=trim(p_phone) WHERE id=auth.uid();IF NOT FOUND THEN RAISE EXCEPTION 'Profile unavailable';END IF;IF p_representative_phone IS NOT NULL THEN IF length(trim(p_representative_phone)) NOT BETWEEN 7 AND 30 THEN RAISE EXCEPTION 'Valid representative phone required';END IF;UPDATE public.companies SET representative_phone=trim(p_representative_phone) WHERE user_id=auth.uid();END IF;END $$;
CREATE FUNCTION public.verify_portal_identity(p_user uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden';END IF;UPDATE public.profiles SET national_id_verified_at=now() WHERE id=p_user AND national_id ~ '^[0-9]{14}$';IF NOT FOUND THEN RAISE EXCEPTION 'Valid identity required';END IF;END $$;
REVOKE ALL ON FUNCTION public.save_portal_account(jsonb),public.save_contact_details(text,text),public.verify_portal_identity(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.save_portal_account(jsonb),public.save_contact_details(text,text),public.verify_portal_identity(uuid) TO authenticated;